def install(self):
        self.check()
        if self.installed or sys.getprofile() is not None:self.refuse('Reused or already profiled route.')
        self.installed=True;self.active=True
        sys.addaudithook(self.audit);sys.setprofile(self.profile)

def check(self):
        try:
            if self.failed or self.pid_reader()!=self.pid:self.refuse('Poisoned or forked route.')
            if json.dumps(self.bindings,sort_keys=True)!=self.binding_bytes:self.refuse('Bindings mutated.')
            if self.effective_reader()!=environment() or self.kernel_reader()!=environment():self.refuse('Exact native import environment required.')
            for b in self.bindings.values():
                s=Path(b['path']).stat()
                if [s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns,s.st_ctime_ns]!=b['stat']:
                    self.refuse('Source/cache/package-lock identity changed.')
            return True
        except BaseException:self.failed=True;raise

def audit(self,event,args):
        if not self.active:return
        # These checks constrain the cooperative Python import route. Native C
        # syscalls and arbitrary interpreter tampering are outside this guard.
        if event.startswith('subprocess.') or event in ('os.system','os.fork','os.forkpty','os.exec','os.posix_spawn','os.spawn'):
            self.refuse('Child/process launch refused: '+event)
        if event in ('os.remove','os.rename','os.rmdir','os.link','os.symlink','os.truncate','os.chmod','os.chown'):
            self.refuse('Filesystem mutation refused: '+event)
        if event=='open':
            path,mode,flags=args
            writing=isinstance(flags,int) and bool(flags & (os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND))
            if writing:
                name=os.fsdecode(path) if isinstance(path,(str,bytes,os.PathLike)) else None
                expected=os.O_WRONLY|os.O_APPEND|os.O_CREAT
                if self.failed or name!=self.lock or (flags & ~getattr(os,'O_CLOEXEC',0))!=expected or mode!='a':
                    self.refuse('Only exact existing package-lock append-open allowed.')
                self.check();self.events.append(dict(event=event,path=name,mode=mode,flags=flags))
        elif event=='os.mkdir':
            if self.failed or os.fsdecode(args[0])!=self.lock_parent or not Path(self.lock_parent).is_dir():
                self.refuse('Only existing package-lock parent mkdir check allowed.')
            self.events.append(dict(event=event,path=self.lock_parent))
        elif event=='os.putenv':
            key,value=map(os.fsdecode,args)
            if self.failed or environment().get(key)!=value:self.refuse('Environment mutation refused.',dict(event=event,key=key,value=value))
        elif event=='os.unsetenv':self.refuse('Environment removal refused.',dict(event=event,key=os.fsdecode(args[0])))
        elif event.startswith('fcntl.'):
            if event!='fcntl.lockf':self.refuse('Undeclared lock operation.')
            fd,cmd,length,start,whence=args
            if self.failed or os.readlink('/proc/self/fd/%d'%fd)!=self.lock or cmd not in (fcntl.LOCK_EX|fcntl.LOCK_NB,fcntl.LOCK_UN) or (length,start,whence)!=(None,None,0):
                self.refuse('Only existing package-lock whole-file lock/unlock allowed.')
            self.events.append(dict(event=event,path=self.lock,command=cmd))
        elif event.startswith('socket.'):self.refuse('Network/socket route refused.')

def install(self):
        self.check()
        if self.used or sys.getprofile() is not None:self.refuse('Bridge is single-use and requires no existing profile.')
        self.used=True
        sys.addaudithook(self.audit);sys.setprofile(self.profile);self.active=True

def profile(self,frame,event,arg):
        if not self.active:return
        if event=='c_call' and arg is getattr(os,'register_at_fork',None):
            self.refuse('Filelock at-fork registration requires a separate state binding.','os.register_at_fork',(frame.f_code.co_filename,frame.f_lineno))
        if frame.f_code.co_filename!=self.source:return
        if self.failed:self.refuse('Previously refused import bridge.')
        if frame.f_code not in self.all_codes:self.refuse('Unexpected live module code.',event,(frame.f_code.co_name,))
        if event=='call' and frame.f_code==self.module_code:
            if self.module_seen:self.refuse('Repeated module execution.')
            module=sys.modules.get(self.module_name)
            if not isinstance(module,types.ModuleType) or module.__dict__ is not frame.f_globals or frame.f_globals.get('__name__')!=self.module_name or frame.f_globals.get('__file__')!=self.source:
                self.refuse('Registered module namespace required.')
            self.module=module;self.module_frame=frame;self.module_seen=True
            self.check();self.boundary_events.append(dict(event='module_entry',line=frame.f_lineno));return
        if event=='call' and frame.f_code==self.callback_code:
            if not self.module_seen or self.callback_seen or frame.f_back is not self.module_frame or frame.f_back.f_lineno!=self.call_line or frame.f_globals is not self.module.__dict__:
                self.refuse('Capability must enter once from exact module callsite.')
            callback=frame.f_globals.get('_probe_link_follow_symlinks')
            if not isinstance(callback,types.FunctionType) or callback.__code__!=frame.f_code or callback.__globals__ is not frame.f_globals:
                self.refuse('Live capability function binding differs.')
            self.check()
            self.scratch=lifecycle.FilelockScratch(self.root,callback,self.bindings)
            # Observe the function already entering. Never call scratch.run() or callback().
            self.scratch.used=True;self.scratch.active=True
            self.callback_frame=frame;self.callback_seen=True
            self.boundary_events.append(dict(event='callback_entry',line=frame.f_back.f_lineno));return
        if event=='return' and frame is self.callback_frame:
            self.check();s=self.scratch
            if arg is not True or s.stage!=12 or Path(s.directory).exists() or Path(s.testfile).exists() or list(Path(self.root).iterdir()):
                self.refuse('Capability returned without complete exact scratch lifecycle.','callback_return',(arg,s.stage))
            s.active=False;self.callback_returned=True
            self.boundary_events.append(dict(event='callback_return',value=True,stage=s.stage));return
        if event=='return' and frame is self.module_frame:
            self.check()
            if not self.callback_returned or frame.f_globals.get(self.result_name) is not True:self.refuse('Module returned without the observed capability result.')
            self.module_returned=True;self.boundary_events.append(dict(event='module_return',result=True));return

def audit(self,event,args):
        if not self.active:return
        if event in ('sys.addaudithook','sys.setprofile') and not self.releasing:
            self.refuse('Additional audit/profile registration is unbound.',event,args)
        writing=event=='open' and isinstance(args[2],int) and bool(args[2] & (os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND))
        mutation=event in ('os.mkdir','os.remove','os.rmdir','os.link','os.symlink','os.rename','os.utime','os.chmod','os.chown','os.truncate','shutil.rmtree')
        forbidden=event.startswith(('subprocess.','socket.','fcntl.')) or event in ('os.system','os.fork','os.forkpty','os.exec','os.posix_spawn','os.spawn','os.putenv','os.unsetenv')
        if forbidden:self.refuse('Process/network/environment/lock route refused.',event,args)
        if self.failed and (writing or mutation):self.refuse('Mutation after bridge refusal.',event,args)
        if self.scratch is not None and self.scratch.active:
            try:self.scratch.audit(event,args)
            except BaseException as e:
                detail=self.scratch.first_refusal
                self.refuse(detail['message'] if detail else 'Scratch observation failed: '+type(e).__name__,event,args)
        elif writing or mutation:self.refuse('Write outside capability scope.',event,args)

def install(self):
        self.check()
        if self.used or sys.getprofile() is not None:self.refuse('Single-use observer requires no prior profile.')
        self.used=True
        try:
            self.original['audit'](self.audit)
            sys.audit('ood.registration_args.install',self.install_token)
        except BaseException as error:self.refuse('Observer audit installation raised: '+type(error).__name__)
        if not self.install_seen:self.refuse('Observer audit hook installation was suppressed.')
        sys.setprofile(self.profile)
        sys.addaudithook=self.wrappers['audit'];os.register_at_fork=self.wrappers['fork'];atexit.register=self.wrappers['exit']
        self.active=True

def _bind_callback(self,name,value):
        if type(value) is not types.FunctionType or self.namespace.get(name) is not value:
            self.refuse('Callback object differs from declared namespace.')
        matches=[c for c in self.compiled if c.co_name==name]
        if len(matches)!=1 or value.__code__!=matches[0] or value.__code__.co_filename!=self.source_pin['path'] or value.__globals__ is not self.namespace or value.__module__!=self.module_name or value.__qualname__!=name:
            self.refuse('Callback defining code/namespace differs.')
        if value.__closure__ is not None or value.__defaults__ is not None:
            self.refuse('Unexpected callback closure or positional defaults.')
        refs=self.keyword_references.get(name,{})
        actual=value.__kwdefaults__ or {}
        if list(actual)!=list(refs) or any(actual[k] is not self.namespace[n] for k,n in refs.items()):
            self.refuse('Captured keyword default reference differs.')
        item=dict(fn=value,code=value.__code__,kw_object=value.__kwdefaults__,kw=dict(actual),
                  names=(value.__module__,value.__name__,value.__qualname__),
                  globals={n:self._global(value,n) for n in globals_used(value.__code__)})
        if name in self.bound and self.bound[name]['fn'] is not value:self.refuse('Callback rebound.')
        self.bound[name]=item

def audit(self,event,args):
        if event=='ood.registration_args.install' and len(args)==1 and args[0] is self.install_token:
            self.install_seen=True;return
        if not self.active:return
        if event=='sys.addaudithook':
            if self.native_pending!='audit' or self.native_seen!='entry':self.refuse('Unbound audit registration event.',event,args=args)
        elif event=='sys.setprofile':self.refuse('Profile replacement refused.',event,args=args)
        elif event.startswith(('subprocess.','socket.','fcntl.')) or event in ('os.system','os.fork','os.forkpty','os.exec','os.posix_spawn','os.spawn','os.putenv','os.unsetenv'):
            self.refuse('Process/network/environment/lock route refused.',event,args=args)
        elif event=='open' and isinstance(args[2],int) and args[2]&(os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND):
            self.refuse('Write outside registration observation refused.',event,args=args)
        elif event in ('os.mkdir','os.remove','os.rmdir','os.link','os.symlink','os.rename','os.utime','os.chmod','os.chown','os.truncate','shutil.rmtree'):
            self.refuse('Mutation outside registration observation refused.',event,args=args)

def run(self):
        self.check()
        if self.used:self.refuse('Repeated scratch callback.')
        self.used=True;self.active=True;sys.addaudithook(self.audit)
        try:
            result=self.callback()
            self.check()
            if result is not True or self.stage!=12 or Path(self.directory).exists() or Path(self.testfile).exists() or list(Path(self.root).iterdir()):self.refuse('Incomplete scratch lifecycle.')
            self.active=False
            return dict(result=True,events=self.events,owner_pid=self.pid,scratch_root=self.root,root_retained_empty=True,
                        full_native_import_accepted=False,scientific_execution_accepted=False)
        except BaseException as e:
            self.refuse('Scratch callback failed: '+type(e).__name__)
